		people->Items.push_back(BindingSourceReference(alice));
		CUI_EXPECT_EQ(3, combo.GetItemCount());
		CUI_EXPECT_EQ(3ULL, list.Items.size());

		list.Items.push_back(ListViewItem(L"manual"));
		CUI_EXPECT_FALSE(list.GetItemsSource());
