		manual.SetSelectedValue(BindingValue(L"Two"));
		CUI_EXPECT_EQ(1, manual.SelectedIndex);
		std::wstring manualValue;
		CUI_EXPECT_TRUE(manual.GetSelectedValue().TryGet(manualValue));
