		CUI_EXPECT_TRUE(gap != nullptr);
		CUI_EXPECT_TRUE(itemHeight != nullptr);
		CUI_EXPECT_TRUE(itemCornerRatio != nullptr);
		CUI_EXPECT_TRUE(separatorColor != nullptr);
