		for (auto& node : changed.Nodes)
			if (node.Name == L"peopleCombo")
				node.Props["metadata"]["SelectedValuePath"]["value"] = "Rank";
		CUI_EXPECT_TRUE(state->SetValue(L"SelectedId", 20));
		DesignerModel::RuntimeDocumentReloadMode mode{};
