		if (authoritativeName)
		{
			CUI_EXPECT_FALSE(authoritativeName->CanRead);
			CUI_EXPECT_TRUE(authoritativeName->CanWrite);
			CUI_EXPECT_FALSE(authoritativeName->CanObserve);
		}

