		CUI_EXPECT_NEAR(34.0f / 255.0f, caption->ForeColor.r, 0.0001f);
		CUI_EXPECT_NEAR(85.0f / 255.0f, caption->ForeColor.g, 0.0001f);
		CUI_EXPECT_NEAR(136.0f / 255.0f, caption->ForeColor.b, 0.0001f);
