		CUI_EXPECT_TRUE(card->AdvanceVisualStateAnimations(recoveryTick + 150));
		CUI_EXPECT_FALSE(card->HasActiveVisualStateAnimations());
		CUI_EXPECT_NEAR(8.0f, chrome->ValidationCornerRadius, 0.0001f);

