		CUI_EXPECT_FALSE(DesignerModel::RuntimeDocumentLoader::Reload(
			invalidRuntime, runtime, {}, &reloadMode, &error));
		CUI_EXPECT_TRUE(runtime.FindControlByName(L"card") == retainedCard);

		Control directRuntimeProbe;
