		CUI_EXPECT_NEAR(1.0f, readBrush(solid).Color.r, 0.001f);
		CUI_EXPECT_NEAR(0.9f, readBrush(linear).EndPoint.x, 0.001f);
		CUI_EXPECT_NEAR(0.6f, readBrush(radial).RadiusY, 0.001f);

		(void)go(L"Idle");
		tick = go(L"Animate", true);
