	runner.Add("Text search replace and caret coordinates stay editor consistent", []
	{
		const std::wstring text = L"Alpha alpha ALPHA";
		CuiTextEdit::FindOptions insensitive;
		CUI_EXPECT_EQ(0, CuiTextEdit::FindText(text, L"alpha", 0, false, insensitive));
		CUI_EXPECT_EQ(6, CuiTextEdit::FindText(text, L"alpha", 1, false, insensitive));
		CUI_EXPECT_EQ(12, CuiTextEdit::FindText(text, L"alpha", -1, true, insensitive));

		CuiTextEdit::FindOptions exact;
		exact.matchCase = true;
		exact.wrap = false;
		CUI_EXPECT_EQ(6, CuiTextEdit::FindText(text, L"alpha", 0, false, exact));
		CUI_EXPECT_EQ(-1, CuiTextEdit::FindText(text, L"alpha", 7, false, exact));
		CUI_EXPECT_FALSE(CuiTextEdit::MatchesAt(text, L"alpha", 0, true));
		CUI_EXPECT_TRUE(CuiTextEdit::MatchesAt(text, L"alpha", 0, false));

		const auto replaced = CuiTextEdit::ReplaceAllText(
			text, L"alpha", L"item", false);
		CUI_EXPECT_EQ(3ULL,
			static_cast<unsigned long long>(replaced.replacements));
		CUI_EXPECT_EQ(std::wstring(L"item item item"), replaced.text);
		const auto nonOverlapping = CuiTextEdit::ReplaceAllText(
			L"aaaa", L"aa", L"b", true);
		CUI_EXPECT_EQ(2ULL,
			static_cast<unsigned long long>(nonOverlapping.replacements));
		CUI_EXPECT_EQ(std::wstring(L"bb"), nonOverlapping.text);
		const auto unchanged = CuiTextEdit::ReplaceAllText(
			text, L"", L"ignored", false);
		CUI_EXPECT_EQ(0ULL,
			static_cast<unsigned long long>(unchanged.replacements));
		CUI_EXPECT_EQ(text, unchanged.text);

		const std::wstring positions = L"A\r\n\xD83D\xDE00" L"B\nZ";
		const auto firstLine = CuiTextEdit::GetTextPosition(positions, 1);
		CUI_EXPECT_EQ(1ULL, static_cast<unsigned long long>(firstLine.line));
		CUI_EXPECT_EQ(2ULL, static_cast<unsigned long long>(firstLine.column));
		const auto secondLine = CuiTextEdit::GetTextPosition(positions, 3);
		CUI_EXPECT_EQ(2ULL, static_cast<unsigned long long>(secondLine.line));
		CUI_EXPECT_EQ(1ULL, static_cast<unsigned long long>(secondLine.column));
		const auto afterEmoji = CuiTextEdit::GetTextPosition(positions, 5);
		CUI_EXPECT_EQ(2ULL, static_cast<unsigned long long>(afterEmoji.line));
		CUI_EXPECT_EQ(2ULL, static_cast<unsigned long long>(afterEmoji.column));
		const auto thirdLine = CuiTextEdit::GetTextPosition(positions, 7);
		CUI_EXPECT_EQ(3ULL, static_cast<unsigned long long>(thirdLine.line));
		CUI_EXPECT_EQ(1ULL, static_cast<unsigned long long>(thirdLine.column));

		RichTextBox editor(L"alpha beta", 0, 0, 240, 100);
		int selectionChanges = 0;
		editor.OnSelectionChanged +=
			[&selectionChanges](Control*) { selectionChanges++; };
		editor.Select(0, 5);
		CUI_EXPECT_EQ(1, selectionChanges);
		editor.Select(0, 5);
		CUI_EXPECT_EQ(1, selectionChanges);
		editor.InsertText(L"");
		CUI_EXPECT_EQ(std::wstring(L" beta"), editor.Text);
		CUI_EXPECT_EQ(2, selectionChanges);
		editor.Undo();
		CUI_EXPECT_EQ(std::wstring(L"alpha beta"), editor.Text);
		CUI_EXPECT_EQ(3, selectionChanges);
		CUI_EXPECT_EQ(5, editor.GetSelectionLength());
	});

	runner.Add("Designer document graph centralizes identity parent and order resolution", []
	{
		DesignerModel::DesignDocument document;
		document.NextStableId = 40;
		DesignerModel::DesignNode lateChild;
		lateChild.Id = 30;
		lateChild.ParentId = 10;
		lateChild.ParentRef = L"container";
		lateChild.Name = L"lateChild";
		lateChild.Type = UIClass::UI_Button;
		lateChild.Order = 2;
		document.Nodes.push_back(std::move(lateChild));
		DesignerModel::DesignNode parent;
		parent.Id = 10;
		parent.Name = L"container";
		parent.Type = UIClass::UI_Panel;
		parent.Order = 0;
		document.Nodes.push_back(std::move(parent));
		DesignerModel::DesignNode earlyChild;
		earlyChild.Id = 20;
		earlyChild.ParentId = 10;
		earlyChild.ParentRef = L"container";
		earlyChild.Name = L"earlyChild";
		earlyChild.Type = UIClass::UI_Button;
		earlyChild.Order = 1;
		document.Nodes.push_back(std::move(earlyChild));

		DesignerModel::DesignDocumentGraph graph;
		std::wstring error;
		CUI_EXPECT_TRUE(DesignerModel::DesignDocumentGraph::Build(
			document, graph, &error));
		CUI_EXPECT_EQ(30, graph.MaxStableId());
		CUI_EXPECT_EQ(1ULL, graph.Roots().size());
		CUI_EXPECT_EQ(1ULL, graph.Roots()[0]);
		const auto children = graph.ChildrenOf(L"container");
		CUI_EXPECT_EQ(2ULL, children.size());
		CUI_EXPECT_EQ(2ULL, children[0]);
		CUI_EXPECT_EQ(0ULL, children[1]);
		CUI_EXPECT_EQ(0ULL, graph.FindById(30)->SourceIndex);
		CUI_EXPECT_EQ(2ULL,
			graph.FindByName(L"earlyChild")->SourceIndex);
		CUI_EXPECT_EQ(std::wstring(L"container"),
			graph.Nodes()[0].ParentKey);

		auto missingParentId = document;
		missingParentId.Nodes.front().ParentId = 0;
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentGraph::Build(
			missingParentId, graph, &error));
		auto negativeParentId = document;
		negativeParentId.Nodes[1].ParentId = -1;
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentGraph::Build(
			negativeParentId, graph, &error));
	});

	runner.Add("Designer materialization pool owns rollback and transfers controls", []
	{
		struct TrackedControl final : Control
		{
			explicit TrackedControl(int& destroyed) : Destroyed(&destroyed) {}
			~TrackedControl() override { ++*Destroyed; }
			int* Destroyed;
		};

		DesignerModel::DesignDocument document;
		for (int id = 1; id <= 3; ++id)
		{
			DesignerModel::DesignNode node;
			node.Id = id;
			node.Name = L"control" + std::to_wstring(id);
			node.Type = UIClass::UI_Button;
			document.Nodes.push_back(std::move(node));
		}
		document.NextStableId = 4;
		DesignerModel::DesignDocumentGraph graph;
		std::wstring error;
		CUI_EXPECT_TRUE(DesignerModel::DesignDocumentGraph::Build(
			document, graph, &error));

		int destroyed = 0;
		{
			DesignerModel::DesignDocumentControlPool pool;
			CUI_EXPECT_TRUE(DesignerModel::DesignDocumentControlPool::Build(
				document, graph,
				[&](const DesignerModel::DesignNode&)
				{ return std::make_unique<TrackedControl>(destroyed); },
				pool, &error));
			CUI_EXPECT_EQ(3ULL, pool.PendingCount());
			CUI_EXPECT_EQ(2, pool.FindByName(L"control2")->DesignId);
			CUI_EXPECT_EQ(pool.FindById(2), pool.FindByName(L"control2"));

			Control runtimeRoot;
			auto attached = pool.TakeByName(L"control2");
			CUI_EXPECT_TRUE(attached != nullptr);
			runtimeRoot.AddOwned(std::move(attached));
			CUI_EXPECT_EQ(2ULL, pool.PendingCount());
			CUI_EXPECT_EQ(runtimeRoot.GetChild(0),
				runtimeRoot.FindControlByDesignId(2));
		}
		CUI_EXPECT_EQ(3, destroyed);

		DesignerModel::DesignDocumentControlPool rejected;
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentControlPool::Build(
			document, graph,
			[](const DesignerModel::DesignNode&)
			{ return std::unique_ptr<Control>{}; },
			rejected, &error));
		CUI_EXPECT_EQ(0ULL, rejected.PendingCount());
	});

